object.script:
local TPU = 1 local active = false local valve, target, rate = 0, 0, 0 local buf, sum, prev = {}, 0 local v = {0}
local function Consumption(v) if not prev then prev = v return end local d = prev - v prev = v if #buf == TPU then sum = sum - buf[1] table.remove(buf, 1) end buf[#buf + 1] = d sum = sum + d return sum / #buf * 60 end
local function pressureStab(active, valve, target, rate) if not active then return 0 end local err = target - rate if math.abs(err) < 0.001 then return valve end valve = valve + err * 0.02 return math.max(0, math.min(1, valve)) end
function onTick() n = input.getBool(1) pressure = input.getNumber(1) m = property.getNumber("Rate") cons = Consumption(pressure)
v[1] = pressureStab(n, v[1], m, cons) output.setNumber(1, v[1]) output.setNumber(32, cons) end

